import doctest
import os
import sys
import unittest

here = os.path.dirname(__file__)
readme_path = os.path.join(here, "..", "README.rst")


def additional_tests():
    """Entry point used by "setup.py test" / unittest's load_tests protocol."""
    if sys.maxunicode >= 0x10000:
        return doctest.DocFileSuite("../README.rst")
    else:
        return doctest.DocFileSuite()


class TestReadme(unittest.TestCase):
    """Run the examples in README.rst as doctests.

    test_readme.additional_tests() above is only picked up by unittest, so
    this wrapper makes sure the doctests also run under pytest.
    """

    @unittest.skipIf(sys.maxunicode < 0x10000, "narrow build")
    def test_readme(self):
        results = doctest.testfile(readme_path, module_relative=False)
        self.assertEqual(0, results.failed)
        self.assertTrue(results.attempted > 0)


if __name__ == "__main__":
    unittest.main()

